import re, json, hashlib
from pathlib import Path
from html.parser import HTMLParser
class Article(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip=0
        self.parts=[]
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style'): self.skip+=1
        if tag in ('p','li','h1','h2','h3','tr'): self.parts.append('\n')
    def handle_endtag(self, tag):
        if tag in ('script','style'): self.skip=max(0,self.skip-1)
        if tag in ('p','li','h1','h2','h3','tr'): self.parts.append('\n')
    def handle_data(self, data):
        if not self.skip: self.parts.append(data)
p=Path('products/distribution/sqlite-lemon-squeezy/raw/fees.html')
raw=p.read_bytes()
parser=Article()
parser.feed(raw.decode())
lines=[' '.join(s.split()) for s in ''.join(parser.parts).splitlines()]
hits=list(dict.fromkeys(s for s in lines if len(s)<550 and re.search(r'5%|50¢|0\.50|1\.5%|payout|PayPal',s,re.I)))
out={'source':'https://docs.lemonsqueezy.com/help/getting-started/fees','sha256':hashlib.sha256(raw).hexdigest(),'excerpts':hits[:45]}
print(json.dumps(out,ensure_ascii=False))
